import {parameters,MODEL,waveSample,geometric,normals} from './physics.js';
export async function createEngine(width=160,height=96,onLost=()=>{}){
 if(!globalThis.navigator?.gpu)throw new Error('此浏览器未提供 WebGPU');
 const adapter=await navigator.gpu.requestAdapter({powerPreference:'low-power'});if(!adapter)throw new Error('未找到可用的 WebGPU 适配器');
 const device=await adapter.requestDevice();device.addEventListener('uncapturederror',e=>onLost(e.error?.message||'WebGPU validation error'));device.lost.then(info=>onLost(info.message||'WebGPU 设备连接已中断'));
 const source=await (await fetch('./kernel.wgsl')).text();const module=device.createShaderModule({code:source});const diagnostics=await module.getCompilationInfo();const errors=diagnostics.messages.filter(m=>m.type==='error');if(errors.length)throw new Error(errors.map(m=>`WGSL ${m.lineNum}:${m.linePos} ${m.message}`).join('\n'));
 const pipeline=await device.createComputePipelineAsync({layout:'auto',compute:{module,entryPoint:'main'}});
 const size=width*height*16;const buffer=device.createBuffer({size,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_SRC});const uniforms=device.createBuffer({size:64,usage:GPUBufferUsage.UNIFORM|GPUBufferUsage.COPY_DST});const read=device.createBuffer({size,usage:GPUBufferUsage.MAP_READ|GPUBufferUsage.COPY_DST});
 const group=device.createBindGroup({layout:pipeline.getBindGroupLayout(0),entries:[{binding:0,resource:{buffer:uniforms}},{binding:1,resource:{buffer}}]});let spp=0;
 return {width,height,type:'WebGPU',reset(){spp=0;},async step(s,batch=4){const p=parameters(s);device.queue.writeBuffer(uniforms,0,new Float32Array([width,height,MODEL.spanX,MODEL.spanY,p.wavelength,p.L,p.width,p.separation,p.sigma0,p.sourceSigma,p.height,p.tail,spp,batch,0,0]));device.pushErrorScope('validation');const e=device.createCommandEncoder();const pass=e.beginComputePass();pass.setPipeline(pipeline);pass.setBindGroup(0,group);pass.dispatchWorkgroups(Math.ceil(width/8),Math.ceil(height/8));pass.end();e.copyBufferToBuffer(buffer,0,read,0,size);device.queue.submit([e.finish()]);await read.mapAsync(GPUMapMode.READ);const data=new Float32Array(read.getMappedRange().slice(0));read.unmap();const validation=await device.popErrorScope();if(validation)throw new Error(validation.message);spp+=batch;return {data,spp};},destroy(){buffer.destroy();read.destroy();uniforms.destroy();device.destroy();}};
}
export function createReferenceEngine(width=96,height=60){let spp=0,data=new Float32Array(width*height*4);return {width,height,type:'CPU 参考',reset(){spp=0;data.fill(0);},async step(s,batch=1){const p=parameters(s);for(let y=0;y<height;y++){for(let x=0;x<width;x++){const i=y*width+x,X=((x+.5)/width-.5)*MODEL.spanX,Y=((y+.5)/height-.5)*MODEL.spanY;for(let j=0;j<batch;j++){const [a,b]=normals(i,spp+j),v=waveSample(X,Y,a,b,p);data[i*4]+=v;data[i*4+1]+=v*v;}if(!spp)data[i*4+2]=geometric(X,Y,p);data[i*4+3]+=batch;}if(y%8===0)await new Promise(r=>setTimeout(r,0));}spp+=batch;return {data:data.slice(),spp};},destroy(){}};}
